@@ -501,6 +501,42 @@ workflows:
         assert!(result.success);
     }

+    #[test]
+    fn execute_dry_run_prints_commands() {
+        let config = r#"
+app_name: Test Project
+steps:
+  install:
+    command: npm install
+  build:
+    command: npm run build
+workflows:
+  default:
+    steps: [install, build]
+"#;
+        let temp = setup_project(config);
+        let args = RunArgs {
+            dry_run: true,
+            ..Default::default()
+        };
+        let cmd = RunCommand::new(temp.path(), args);
+        let mut ui = MockUI::new();
+
+        let result = cmd.execute(&mut ui).unwrap();
+
+        assert!(result.success);
+        assert!(
+            ui.has_message("Would run: npm install"),
+            "expected 'Would run: npm install' in messages: {:?}",
+            ui.messages()
+        );
+        assert!(
+            ui.has_message("Would run: npm run build"),
+            "expected 'Would run: npm run build' in messages: {:?}",
+            ui.messages()
+        );
+    }
+
     #[test]
     fn execute_real_workflow() {
         let config = r#"
