     /// Requirements that are provided by the environment and should skip gap checks.
     pub provided_requirements: HashSet<String>,
@@ -665,6 +665,11 @@ impl<'a> WorkflowRunner<'a> {
                             None
                         };
                         spinner.finish_success(&format!("{} ({})", step_name, duration_str));
+                        if options.dry_run {
+                            if let Some(ref output) = result.output {
+                                ui.message(&format!("    {}", output));
+                            }
+                        }
                         let mut r = result;
                         r.recovery_detail = detail;
                         final_result = Some(r);
diff --git a/tests/cli_test.rs b/tests/cli_test.rs
index 08e0c68..a55ca8e 100644
